CustomField.formula:
IF(
OR(
AND(ISPICKVAL(Evaluation_Type__c,'Customer Resolution Assessment'),AssessmentOutcomePass__c == true),
AND(ISPICKVAL(Evaluation_Type__c,'Frontline Assessment'), AssessmentOutcomeFrontlinePass__c == true)
),'Pass',
IF(AssessmentOutcomeFail__c  == true,'Fail',
IF(
OR(
AND(ISPICKVAL(Evaluation_Type__c,'Customer Resolution Assessment'),AssessmentOutcomePassFeedback__c == true),
AND(ISPICKVAL(Evaluation_Type__c,'Frontline Assessment'),AssessmentOutcomeFLPassWithFeedback__c == true)
),'Pass With Feedback',
IF(AssessmentOutcomeFailOutControl__c == true,'Fail – outside of complaint handler’s control','')
)
)
)
